import { trackFormSubmit, trackFormError } from "@/lib/analytics";
import { getUTMParams } from "@/lib/utm";
import { useEffect, useRef, useState } from "react";
import { TurnstileField } from "@/components/contact/TurnstileField";

function cleanString(value, maxLength) {
  return String(value || "")
    .trim()
    .slice(0, maxLength);
}

function isValidEmail(value) {
  if (!value || value.length > 254) return false;

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

export default function ModalContactForm({ onClose }) {
  const formRef = useRef(null);
  const turnstileRef = useRef(null);

  const [turnstileToken, setTurnstileToken] = useState("");

  const [formStartedAt, setFormStartedAt] = useState("");

  const [submitting, setSubmitting] = useState(false);

  const [submitted, setSubmitted] = useState(false);

  const [error, setError] = useState("");

  useEffect(() => {
    setFormStartedAt(new Date().toISOString());

    function handleKeyDown(event) {
      if (event.key === "Escape" && !submitting) {
        onClose?.();
      }
    }

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [onClose, submitting]);

  async function handleSubmit(event) {
    event.preventDefault();

    if (submitting) return;

    setError("");

    const formElement = formRef.current;

    if (!formElement?.reportValidity()) {
      return;
    }

    setSubmitting(true);

    let requestStarted = false;

    try {
      const form = new FormData(formElement);

      const name = cleanString(form.get("name"), 120);

      const email = cleanString(form.get("email"), 254).toLowerCase();

      const message = cleanString(form.get("message"), 2_000);

      const companyWebsite = cleanString(form.get("companyWebsite"), 500);

      if (name.length < 2) {
        throw new Error("Please enter your name.");
      }

      if (!isValidEmail(email)) {
        throw new Error("Please enter a valid email address.");
      }

      if (message.length < 5) {
        throw new Error("Please enter a brief message.");
      }

      if (!turnstileToken) {
        throw new Error("Please complete the verification.");
      }

      const payload = {
        ...getUTMParams(),
        ...getUTMParams(),
        page: window.location.pathname,
        formType: "modal",
        name,
        email,
        message,

        companyWebsite,
        honeypot: companyWebsite,

        formStartedAt: formStartedAt || new Date().toISOString(),

        turnstileToken,
      };

      requestStarted = true;

      const response = await fetch("/api/contact", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const json = await response.json().catch(() => ({}));

      if (!response.ok || json?.ok !== true || json?.accepted !== true) {
        throw new Error(json?.error || (response.status === 429 ? "Too many attempts. Please call (904) 434-6318." : "We couldn't submit the form."));
      }

      trackFormSubmit({ form_id: "ModalContactForm", form_location: "ModalContactForm", page: window.location.pathname });
      setSubmitted(true);
      formElement.reset();
    } catch (err) {
      trackFormError("ModalContactForm", requestStarted ? "submission_failed" : "validation");
      console.error("Modal contact form error:", err);

      if (requestStarted) {
        turnstileRef.current?.reset();
      }

      setError(
        err instanceof Error
          ? err.message
          : "Something went wrong. Please try again.",
      );
    } finally {
      setSubmitting(false);
    }
  }

  function handleBackdropClick(event) {
    if (event.target === event.currentTarget && !submitting) {
      onClose?.();
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-contact-heading"
      onMouseDown={handleBackdropClick}
    >
      <div className="w-full max-w-md rounded bg-white p-6 shadow-lg">
        {submitted ? (
          <div>
            <h2
              id="modal-contact-heading"
              className="text-xl font-semibold text-navy"
            >
              Request received
            </h2>

            <p className="mt-2 text-green-700">
              Submitted! We&apos;ll be in touch.
            </p>

            <div className="mt-6 flex justify-end">
              <button
                type="button"
                onClick={onClose}
                className="rounded bg-navy px-4 py-2 text-white"
              >
                Close
              </button>
            </div>
          </div>
        ) : (
          <>
            <h2
              id="modal-contact-heading"
              className="mb-4 text-xl font-semibold text-navy"
            >
              Contact Us
            </h2>

            <form
          data-analytics-form="ModalContactForm"
              ref={formRef}
              onSubmit={handleSubmit}
              className="space-y-4"
              noValidate
            >
              <div
                className="absolute left-[-10000px] top-auto h-px w-px overflow-hidden"
                aria-hidden="true"
              >
                <label htmlFor="modal-company-website">Company website</label>

                <input
                  id="modal-company-website"
                  type="text"
                  name="companyWebsite"
                  tabIndex={-1}
                  autoComplete="off"
                />
              </div>

              <div>
                <label
                  htmlFor="modal-name"
                  className="mb-1 block text-sm font-medium"
                >
                  Name
                </label>

                <input
                  id="modal-name"
                  name="name"
                  type="text"
                  autoComplete="name"
                  maxLength={120}
                  required
                  className="w-full rounded border p-2"
                />
              </div>

              <div>
                <label
                  htmlFor="modal-email"
                  className="mb-1 block text-sm font-medium"
                >
                  Email
                </label>

                <input
                  id="modal-email"
                  name="email"
                  type="email"
                  autoComplete="email"
                  inputMode="email"
                  maxLength={254}
                  required
                  className="w-full rounded border p-2"
                />
              </div>

              <div>
                <label
                  htmlFor="modal-message"
                  className="mb-1 block text-sm font-medium"
                >
                  Message
                </label>

                <textarea
                  id="modal-message"
                  name="message"
                  rows={4}
                  maxLength={2_000}
                  required
                  className="w-full rounded border p-2"
                />
              </div>

              <TurnstileField
                ref={turnstileRef}
                action="contact_modal"
                onTokenChange={setTurnstileToken}
                onVerificationError={setError}
              />

              <div aria-live="polite">
                {error ? (
                  <p role="alert" className="text-sm text-red-600">
                    {error}
                  </p>
                ) : null}
              </div>

              <div className="flex justify-end space-x-2">
                <button
                  type="button"
                  onClick={onClose}
                  disabled={submitting}
                  className="rounded bg-gray-200 px-4 py-2 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  Cancel
                </button>

                <button
                  type="submit"
                  disabled={submitting || !turnstileToken}
                  aria-busy={submitting}
                  className="rounded bg-navy px-4 py-2 text-white disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {submitting ? "Sending..." : "Send"}
                </button>
              </div>
            </form>
          </>
        )}
      </div>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { getUTMParams } from "@/lib/utm";
import { trackFormSubmit, trackFormError } from "@/lib/analytics";
import { TurnstileField } from "./contact/TurnstileField";

import { ALLOWED_SERVICES, CONTACT_SERVICES } from "@/lib/contact-services";

const initialState = {
  formType: "standard",
  name: "",
  phone: "",
  email: "",
  service: "",
  message: "",
  financing: "",
  companyWebsite: "",
  utm_source: "",
  utm_medium: "",
  utm_campaign: "",
  utm_term: "",
  utm_content: "",
};

function cleanString(value, maxLength) {
  return String(value || "")
    .trim()
    .slice(0, maxLength);
}

function isValidPhone(value) {
  const digits = String(value || "").replace(/\D/g, "");

  return (
    digits.length === 10 || (digits.length === 11 && digits.startsWith("1"))
  );
}

function isValidEmail(value) {
  if (!value) return true;
  if (value.length > 254) return false;

  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

export default function StandardContactForm() {
  const formRef = useRef(null);
  const turnstileRef = useRef(null);

  const [turnstileToken, setTurnstileToken] = useState("");

  const [formData, setFormData] = useState(initialState);

  const [attributionFields, setAttributionFields] = useState({});

  const [formStartedAt, setFormStartedAt] = useState("");

  const [submitted, setSubmitted] = useState(false);

  const [isSubmitting, setIsSubmitting] = useState(false);

  const [error, setError] = useState("");

  useEffect(() => {
    const startedAt = new Date().toISOString();

    setFormStartedAt(startedAt);

    let stored = {};

    try {
      const parsed = JSON.parse(localStorage.getItem("bc_attribution") || "{}");

      if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
        stored = parsed;
      }
    } catch {
      stored = {};
    }

    let utms = {};

    try {
      utms = getUTMParams() || {};
    } catch {
      utms = {};
    }

    const current = {
      ...utms,
      referrer: getUTMParams().referrer || stored.referrer || document.referrer || "",
      landing_page_url: getUTMParams().landing_page_url || stored.landing_page_url || window.location.href,
      page: window.location.pathname,
      device: /Mobi|Android/i.test(navigator.userAgent) ? "mobile" : "desktop",
      timestamp: startedAt,
      timezone:
        typeof Intl !== "undefined"
          ? Intl.DateTimeFormat().resolvedOptions().timeZone
          : stored.timezone || "",
      page_variant: "standard_contact_form_v1",
    };

    const merged = {
      ...stored,
      ...current,
    };

    try {
      localStorage.setItem("bc_attribution", JSON.stringify(merged));
    } catch {
      // Continue without persisted attribution.
    }

    setAttributionFields(merged);

    setFormData((previous) => ({
      ...previous,
      ...utms,
    }));
  }, []);

  function handleChange(event) {
    const { name, value, type, checked } = event.target;

    setFormData((previous) => ({
      ...previous,
      [name]: type === "checkbox" ? checked : value,
    }));
  }

  async function handleSubmit(event) {
    event.preventDefault();

    if (isSubmitting) return;

    setError("");

    if (!formRef.current?.reportValidity()) {
      return;
    }

    setIsSubmitting(true);

    let requestStarted = false;

    try {
      const name = cleanString(formData.name, 120);

      const phone = cleanString(formData.phone, 30);

      const email = cleanString(formData.email, 254).toLowerCase();

      const service = cleanString(formData.service, 100);

      const message = cleanString(formData.message, 2_000);

      const companyWebsite = cleanString(formData.companyWebsite, 500);

      if (name.length < 2) {
        throw new Error("Please enter your name.");
      }

      if (!isValidPhone(phone)) {
        throw new Error("Please enter a valid phone number.");
      }

      if (!isValidEmail(email)) {
        throw new Error("Please enter a valid email address.");
      }

      if (!ALLOWED_SERVICES.has(service)) {
        throw new Error("Please select a valid service.");
      }

      if (!turnstileToken) {
        throw new Error("Please complete the verification.");
      }

      const payload = {
        ...getUTMParams(),
        ...formData,
        ...attributionFields,

        formType: "standard",
        name,
        phone,
        email,
        service,
        message,

        companyWebsite,
        honeypot: companyWebsite,

        formStartedAt: formStartedAt || new Date().toISOString(),

        turnstileToken,
      };

      requestStarted = true;

      const response = await fetch("/api/contact", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });

      const json = await response.json().catch(() => ({}));

      if (!response.ok || json?.ok !== true || json?.accepted !== true) {
        throw new Error(json?.error || (response.status === 429 ? "Too many attempts. Please call (904) 434-6318." : "Submission failed."));
      }

      if (json?.accepted === true) {
        trackFormSubmit({
          service_requested: service,
          form_name: "Standard Contact Form",
          form_location: "StandardContactForm",
          page: window.location.pathname,
          intent:
            formData.financing === "Yes"
              ? "service request with financing interest"
              : "service request",
        });
      }

      setSubmitted(true);

      setFormData({
        ...initialState,
      });
    } catch (err) {
      trackFormError("StandardContactForm", requestStarted ? "submission_failed" : "validation");
      console.error("Standard contact form error:", err);

      if (requestStarted) {
        turnstileRef.current?.reset();
      }

      setError(
        err instanceof Error
          ? err.message
          : "Something went wrong. Please try again.",
      );
    } finally {
      setIsSubmitting(false);
    }
  }

  if (submitted) {
    return (
      <div className="rounded-2xl bg-green-100 p-6 text-green-800 shadow-md">
        <h2 className="font-heading text-2xl font-bold">Request received</h2>

        <p className="mt-2 text-base leading-7">
          Thanks. A member of the team will follow up shortly.
        </p>
      </div>
    );
  }

  return (
    <form
          data-analytics-form="StandardContactForm"
      ref={formRef}
      onSubmit={handleSubmit}
      className="w-full rounded-2xl bg-white p-6 shadow-xl sm:p-8"
      noValidate
    >
      <h2 className="font-heading text-3xl font-bold text-darkText sm:text-4xl">
        Talk to Our Restoration Team
      </h2>

      <p className="mt-3 text-base leading-7 text-gray-600">
        Tell us what happened and how to reach you. Emergency requests can also
        call directly for faster response.
      </p>

      <div
        className="absolute left-[-10000px] top-auto h-px w-px overflow-hidden"
        aria-hidden="true"
      >
        <label htmlFor="standard-company-website">Company website</label>

        <input
          id="standard-company-website"
          type="text"
          name="companyWebsite"
          value={formData.companyWebsite}
          onChange={handleChange}
          tabIndex={-1}
          autoComplete="off"
        />
      </div>

      <div className="mt-8 space-y-5">
        <div>
          <label
            htmlFor="standard-name"
            className="mb-2 block text-sm font-medium text-gray-800"
          >
            Name
          </label>

          <input
            id="standard-name"
            type="text"
            name="name"
            value={formData.name}
            placeholder="Your name"
            onChange={handleChange}
            className="w-full rounded-lg border border-gray-300 px-4 py-3 text-darkText outline-none transition focus:border-aqua focus:ring-2 focus:ring-aqua/20"
            required
            autoComplete="name"
            maxLength={120}
          />
        </div>

        <div>
          <label
            htmlFor="standard-phone"
            className="mb-2 block text-sm font-medium text-gray-800"
          >
            Phone
          </label>

          <input
            id="standard-phone"
            type="tel"
            name="phone"
            value={formData.phone}
            placeholder="(904) 555-1234"
            onChange={handleChange}
            className="w-full rounded-lg border border-gray-300 px-4 py-3 text-darkText outline-none transition focus:border-aqua focus:ring-2 focus:ring-aqua/20"
            required
            autoComplete="tel"
            inputMode="tel"
            maxLength={30}
          />
        </div>

        <div>
          <label
            htmlFor="standard-email"
            className="mb-2 block text-sm font-medium text-gray-800"
          >
            Email <span className="font-normal text-gray-500">(optional)</span>
          </label>

          <input
            id="standard-email"
            type="email"
            name="email"
            value={formData.email}
            placeholder="you@example.com"
            onChange={handleChange}
            className="w-full rounded-lg border border-gray-300 px-4 py-3 text-darkText outline-none transition focus:border-aqua focus:ring-2 focus:ring-aqua/20"
            autoComplete="email"
            inputMode="email"
            maxLength={254}
          />
        </div>

        <div>
          <label
            htmlFor="standard-service"
            className="mb-2 block text-sm font-medium text-gray-800"
          >
            Service Needed
          </label>

          <select
            id="standard-service"
            name="service"
            value={formData.service}
            onChange={handleChange}
            className="w-full rounded-lg border border-gray-300 px-4 py-3 text-darkText outline-none transition focus:border-aqua focus:ring-2 focus:ring-aqua/20"
            required
          >
            <option value="">Select a service</option>
            {CONTACT_SERVICES.map((service) => <option key={service} value={service}>{service}</option>)}
          </select>
        </div>

        <div>
          <label
            htmlFor="standard-message"
            className="mb-2 block text-sm font-medium text-gray-800"
          >
            What happened?{" "}
            <span className="font-normal text-gray-500">(optional)</span>
          </label>

          <textarea
            id="standard-message"
            name="message"
            value={formData.message}
            placeholder="Water leak, visible mold, storm damage, smoke issue, or other restoration need"
            onChange={handleChange}
            className="min-h-[140px] w-full rounded-lg border border-gray-300 px-4 py-3 text-darkText outline-none transition focus:border-aqua focus:ring-2 focus:ring-aqua/20"
            maxLength={2_000}
          />
        </div>

        <div>
          <span className="mb-2 block text-sm font-medium text-gray-800">
            Interested in financing options?
          </span>

          <div className="flex flex-wrap gap-6">
            <label className="inline-flex items-center text-sm text-gray-700">
              <input
                type="radio"
                name="financing"
                value="Yes"
                checked={formData.financing === "Yes"}
                onChange={handleChange}
                className="border-gray-300 text-aqua focus:ring-aqua"
              />

              <span className="ml-2">Yes</span>
            </label>

            <label className="inline-flex items-center text-sm text-gray-700">
              <input
                type="radio"
                name="financing"
                value="No"
                checked={formData.financing === "No"}
                onChange={handleChange}
                className="border-gray-300 text-aqua focus:ring-aqua"
              />

              <span className="ml-2">No</span>
            </label>
          </div>
        </div>

        <TurnstileField
          ref={turnstileRef}
          action="contact_standard"
          onTokenChange={setTurnstileToken}
          onVerificationError={setError}
        />

        {error ? (
          <div
            role="alert"
            className="rounded-lg bg-red-50 px-4 py-3 text-sm text-red-700"
          >
            {error}
          </div>
        ) : null}

        <button
          type="submit"
          disabled={isSubmitting || !turnstileToken}
          aria-busy={isSubmitting}
          className="w-full rounded-lg bg-navy px-6 py-3 font-semibold text-white transition hover:bg-navy-dark disabled:cursor-not-allowed disabled:opacity-70"
        >
          {isSubmitting ? "Submitting..." : "Request Service"}
        </button>
      </div>
    </form>
  );
}

