        schemaOverrides: {
          telephone: "+19044346318",
          address: {
            streetAddress: "14440 Normandy Blvd",
            addressLocality: "Jacksonville",
            addressRegion: "FL",
            postalCode: "32234",
            addressCountry: "US",
          },
          name: "Bold City IAQ",
          url: "https://boldcityiaq.com/ads/emergency-restoration",
